#!/usr/bin/env python3
"""Great-works pass, batch 1: nearest-source characterization edits.
Idempotent: guards on marker substrings and edge (from,to,type)."""
import json
p = '/home/cobe-liu/Developing/spirit-search/research/graph.json'
g = json.load(open(p))
nodes = {n['id']: n for n in g['nodes']}

def set_essay(nid, marker, text):
    n = nodes[nid]
    if marker in n['essay']:
        print('skip set', nid); return
    n['essay'] = text
    print('set', nid)

def add_para(nid, marker, text):
    n = nodes[nid]
    if marker in n['essay']:
        print('skip add', nid); return
    n['essay'] = n['essay'] + '\n\n' + text
    print('add', nid)

def add_edge(f, t, ty, source, title, essay, era):
    for e in g['edges']:
        if e['from'] == f and e['to'] == t and e['type'] == ty:
            print('skip edge', f, t, ty); return
    g['edges'].append({'from': f, 'to': t, 'type': ty, 'source': source,
                       'title': title, 'essay': essay, 'date_added': '2026-10-12', 'era': era})
    print('edge', f, t, ty)

set_essay('hera', 'the poem of housekeeping at war', """The wife at the top of the king-list is the tradition's first study in rival sovereignty. Hesiod closes Zeus' marriages with the politics of generation: 'Lastly, he made Hera his blooming wife: and she was joined in love with the king of gods and men, and brought forth Hebe and Ares and Eileithyia', and then records her answer to his head-birth of Athene, 'But Hera without union with Zeus, for she was very angry and quarrelled with her mate, bare famous Hephaestus' [26]. Motherhood as counter-stroke, in the poem of housekeeping at war which is the Iliad, becomes grand strategy. It is Hera who pities the dying Greeks and dispatches Athene to stay Achilles' hand: 'Juno has sent me, who cares for both of you alike' [1]. It is Hera who has sworn with Athene 'full many a time before all the immortals, that never would we shield Trojans from destruction, not even when all Troy is burning' [1], and who engineers the deception of Zeus in the fourteenth book, borrowing Aphrodite's own tackle: 'the curiously embroidered girdle into which all her charms had been wrought: love, desire, and that sweet flattery which steals the judgement even of the most prudent' [1]. The later mythographers only miniaturize the same character: Heracles 'was driven mad through the jealousy of Hera' and burned his own children [32]. Across the earliest witnesses she never wields a weapon and never needs one; her instruments are the aide, the alliance oath, the borrowed girdle, and the bedroom humiliation of the king. The Odyssey, which repatriates Greek husbands, has no work for her.""")

add_para('apollo', 'suppliant’s wreath'.replace('’',"'") if False else 'a suppliant', """The Iliad opens on his invoice. Chryses comes to ransom his daughter bearing 'the sceptre of Apollo wreathed with a suppliant's wreath' [1]; refused, the priest prays, and 'Apollo heard his prayer. He came down furious' [1], shooting mules and dogs first, then men, 'and all day long the pyres of the dead were burning' [1]. Thence the god's etiquette, constant through the poem: he pays his own servants with arrows and repels trespassers in person. Diomedes, charging Aeneas 'as though he were a god', gets the message shouted to his face: 'think not to match yourself against gods, for men that walk the earth cannot hold their own with the immortals' [1]; Patroclus at the wall is struck three times by no proxy but Apollo's 'own immortal hands' [1], the softening-up that makes Hector easy after. The Odyssey's epithet for the same weapon is the painless shaft, Apollo killing Menelaus' steersman 'then and there with the helm in his hand' [54]. Between the plague book and that verb the god's character is fixed: distance, contract, and a killing that leaves its date.""")

add_para('achilles', 'paid servant in a poor man', """The Odyssey gives him the posthumous audit, and he refuses it. Consoled for being 'a great prince among the dead', he answers: 'Say not a word in death's favour; I would rather be a paid servant in a poor man's house and be above ground than king of kings among the dead' [54]. The Iliad had already staged the same accounting on the field: his horse, given speech for one scene, prophesies his doom, and the man replies only 'You need not do so, for I well know that I am to fall here, far from my dear father' [1]. What he was owed is measurable, and the poem measures it: Agamemnon's shade testifies that Thetis gave funeral games 'beyond' any hero's, and that 'even in death your fame, Achilles, has not been lost, and your name lives evermore among all mankind' [54]. Fame is the only coin the tradition ever pays out to him, and he prices it as worthless against one more day of being alive.""")

add_para('nestor', 'Ajax, Achilles, Patroclus peer of gods', """The Odyssey finds him at home in the third generation, still doing the same job: he receives Telemachus, itemizes the returns ('Our best men all of them fell there: Ajax, Achilles, Patroclus peer of gods in counsel, and my own dear son Antilochus'), and forwards the boy to Menelaus for the rest of the war's news [54]. The Iliad's hauler and adviser has become the Ithaca question's clearing-house; longevity has made him a dispatch office of the heroic world.""")

add_para('poseidon', 'will not kill Ulysses outright', """The Odyssey prices his vendetta precisely. Zeus lays out the terms in the divine council of book 1: Polyphemus 'is son to Neptune by the nymph Thoosa', and 'therefore though he will not kill Ulysses outright, he torments him by preventing him from getting home' [54]. Not a grudge to the death but a licensed harassment, the sea's jurisdiction used as a blockade. Homer's second poem gives the earth-shaker what the first never did: a casus belli and a schedule of damages.""")

add_para('ares', 'defiled King Vulcan', """Odyssey 8 has the tradition laugh at him in open court. Demodocus sings 'the loves of Mars and Venus, and how they first began their intrigue in the house of Vulcan', how 'the sun, who saw what they were about, told Vulcan', and how the smith 'began to forge some chains which none could either unloose or break' [54]. Held naked in the net before all Olympus, the war god's release is commercial: Neptune underwrites the adultery fine, 'if Mars goes away without paying his damages, I will pay you myself' [54], and the freed god absconds to Thrace. Scheduled out of battle by Athene in the first poem, bailed out of the bedroom in the second: the songs agree that war's personification is someone the clever gods can owe.""")

add_para('aphrodite', 'the curiously embroidered girdle', """Homer gives her a wound and a weapon. At Troy, carrying Aeneas from the press, she is speared through the wrist by a mortal and withdraws to Dione, crying 'Proud Diomed, the son of Tydeus, wounded me because I was bearing my dear son Aeneas, whom I love best of all mankind, out of the fight' [1]. The wound is the poem's proof that her faction can be hurt. In book 14 her contribution is ordnance: she lends Hera 'the curiously embroidered girdle into which all her charms had been wrought: love, desire, and that sweet flattery which steals the judgement even of the most prudent' [1], collateral in the one operation that turns the war. In Demodocus' lay she is caught in chains and simply departs for Paphos, 'where is her grove and her altar fragrant with burnt offerings' [54]: no apology recorded, only itinerary. The early poems consistently cost her invulnerability and consistently show her not paying.""")

add_para('iris', 'speaking with the voice of Priam', """In the Iliad her delivery uniform is another person's body. She brings Zeus' bad news to the Trojan muster 'speaking with the voice of Priam's son Polites', comes to Helen 'in the form of her sister-in-law' Laodice, and pulls the wounded Aphrodite out of the press and begs Ares' horses for her [1]. The Odyssey does not speak her name once; in that poem the divine errands all run on Hermes. Between the two earliest epics her route is already fixed: the war-messenger, voice and face always borrowed, keeper only of the one errand Hesiod gives her, the oath-water run [26].""")

add_para('castor-polydeuces', 'die and come to life again', """Odysseus files their whereabouts from below: 'Both these heroes are lying under the earth, though they are still alive, for by a special dispensation of Jove, they die and come to life again, each one of them every other day throughout all time, and they have the rank of gods' [54]. The shame Helen suspects kept them from Troy has been settled, and the settlement is a schedule: one immortality, time-shared between two bodies, the earliest alternating pension in the record. Later witnesses will station them on ships as the Dioscuri; Homer already has the god-rank and the roster.""")

add_para('deucalion', 'the whole people of the earth', """Ovid restores the speeches the mythographers compress. Landed on the emptied earth, Deucalion turns to Pyrrha 'with tears bursting forth': 'O sister, O wife, O thou, the only woman surviving... we two are the whole people of the earth, whatever both the East and the West behold' [60]. The flood hero's character in the Roman redaction is a husband doing arithmetic aloud, and building an argument that ends in prayer: the couple go together to Themis' oracle, and the answer given is the riddling command to 'throw behind your backs the bones of your great mother' [60]. Forethought's line has in him become grief administration: he survives the warning to preside over the census of two.""")

add_para('pyrrha', 'trembling lips', """Ovid gives her the words Apollodorus withholds, and they are a refusal. At Themis' answer, 'Pyrrha is the first by her words to break the silence, and refuses to obey the commands of the Goddess; and begs her, with trembling lips, to grant her pardon, and dreads to offend the shades of her mother' [60]. The tradition's one glimpse of her independence is piety against piety: she will not throw her mother's bones, and must be argued past herself by her husband's reading that the mother is earth and the bones are stones [60]. Pandora's daughter ends the myth doing what her mother never learned: refusing an instruction from the gods until its cost has been reasoned out.""")

add_para('erinyes', 'walks in darkness and knows no ruth', """Homer keeps them, as law keeps them, under the floor of the family. Phoenix stands cursed by his father 'calling the dread Erinyes to witness', and 'the gods, Jove of the world below and awful Proserpine, fulfilled his curse' [1]; Meleager's mother, kneeling and beating the earth, prays her own son dead, 'and Erinys that walks in darkness and knows no ruth heard her from Erebus' [1]. Their jurisdiction extends even over miracles inside the war: when Xanthus the horse is given speech and foretells Achilles' end, he gets the prophecy out and no further: 'When he had thus said the Erinyes stayed his speech' [1]. Three centuries before Aeschylus sat them down in Athens, the Iliad knew them as the powers who enforce curses and censor the unlicensed voice alike.""")

add_para('juno', 'unrelenting hate', """Latin epic supplies the myth the lawyers withheld. Vergil's premise is her memory: Aeneas is driven by 'haughty Juno's unrelenting hate' [35], for the slighted beauty contest and for Carthage. Blocked above, she works below: 'Now Juno to the Stygian sky descends, Solicits hell for aid, and arms the fiends', renting the Fury Allecto to set the Italian war alight [35]. Dryden's note for the operation is the poem's own sneer: 'An act that well became the wife of Jove' [35]. In the Aeneid the women's tutelary of the jurists has become statecraft in opposition: where she cannot veto the fates she inflates the price of Italy, and the cost lands on Dido first.""")

add_para('zeus', 'strangers and beggars are from Jove', """The Odyssey names the social contract he underwrites. Eumaeus the swineherd answers for it to a beggar: 'for all strangers and beggars are from Jove' [54]. Xenios, the guest-protector: the god of suppliants stands behind the poem's entire testing machine, which is why the disguised tester in the poem is always asking for bread.""")

add_para('atlas', 'great columns that keep heaven and earth asunder', """The Odyssey knows a different work order, perhaps the older one: Calypso is 'daughter of the magician Atlas, who looks after the bottom of the ocean, and carries the great columns that keep heaven and earth asunder' [54]. Not the sky-bearer of the Titanomachy file but the pillar-man stationed at the seam, with earth under his charge as well as heaven. Between the two earliest poems the sentence has already hardened into civil engineering.""")

add_para('themis', 'first to come running', """The Iliad keeps her at her assembly post: when Hera returns to Olympus in book 15, shaken from the deception plot, 'lovely Themis' is 'first to come running up to her' with the cup, and is dispatched to 'lead the gods to table' [1]. Usher, cupbearer, convener: the poem stages custom's goddess doing the courtesies the divine parliament cannot survive without.""")

add_para('adam', 'she gave me of the tree', """Genesis gives him twelve words of dialogue, and they are a deposition: 'The woman whom thou gavest to be with me, she gave me of the tree, and I did eat' [18]. The first speech in the man's own record is blame routed through the wife to God, stamped with compliance at the end. The aggadah's triple posterity [19] grows out of exactly this: a founder whose one recorded act of speech is the apportionment of fault.""")

add_para('eve', 'the mother of all living', """Genesis gives her the better line and the name. Questioned, she answers with causality, not blame: 'The serpent beguiled me, and I did eat' [18]. After sentence is passed, Adam names her for the outcome: 'And Adam called his wife's name Eve; because she was the mother of all living' [18]. The curse assigns her the childbirth economy [18]; Ginzberg's strata then re-establish her as the lawful line against the demonic unions of Adam's separation years [19]. From beguiled to 'mother of all living', the witnesses route the whole human fix through her.""")

add_para('methuselah', 'nine hundred sixty and nine years', """The Bible files him as a ledger line with a summit: 'And all the days of Methuselah were nine hundred sixty and nine years: and he died' [18]. Genesis leaves him no speech and no act, only the maximum term; the demon-slaying kingship of the aggadah [19] is the later tradition's answer to the question that line dares you to ask: what is done with nine hundred and sixty-nine years.""")

add_para('dionysus', 'plaintiff with a documented grievance', """Euripides stages the returned god as a plaintiff with a documented grievance. His prologue states the case: 'I am come to this land of Thebes, Dionysus, the son of Zeus, of whom on a day Semele, the daughter of Cadmus, was delivered by a flash of lightning. I have put off the god and taken human shape' [67]. Pentheus' refusal of the rites is answered with madness, rending, and a palace that shakes itself to ruins on cue [67]. Herodotus years before had filed the same arrival as a foreign policy matter: it was Melampus 'who introduced into Greece the name of Bacchus, the ceremonial of his worship, and the procession of the phallus' [55], the god imported through a named middleman rather than born onto Olympus. Between Hesiod's promotion line [26] and the Bacchae there lies the whole mechanism of admission: lightning birth, export, re-entry under protest.""")

if nodes['chiron']['essay'].find('The Iliad grants the exemption') < 0:
    nodes['chiron']['essay'] += '\n\n' + """The naming of him in Homer is already a citation: the wound-herbs come 'by Achilles, who was himself shown them by Chiron, most righteous of all the centaurs' [1]. Most righteous of the centaurs: the Iliad grants the exemption in a comparative clause, as if the violence of the kind were the known quantity and Chiron the documented exception."""
    print('add chiron')

add_para('pericles', 'nicknamed the Olympian', """Plutarch files the character the funeral speech sells. Trained by Anaxagoras, he carried natural philosophy into his oratory, and for that elevation 'he was nicknamed the Olympian', a surname some traced to the city's new buildings, some to his power 'both as a politician and a general' [61]. Plutarch's own verdict is severer than the nickname: the man 'never gave way to feelings of envy or hatred', a serenity 'utterly uncorrupt though possessed of great power' [61]. Thucydides lets him have the last word himself, and it is a fiat of identity: 'I am the same man and do not alter, it is you who change' [56]. Statesman, city-cult, apologist of empire: all three registers quote the same man.""")

add_para('inana', 'man of Anu', """In the earliest Akkadian stratum of the Gilgamesh cycle her neighbor-claim is different: the crown she is attached to is the king's excess. When Erech labors under Gilgamesh's tyranny, the appeal goes to Aruru, and 'Aruru upon hearing this created a man of Anu in her heart' [68]. Enkidu enters the tradition as an engineered counterweight; by the Sumerian witness [17] Inana is the tree's proprietor hiring the strongman. The two strata keep her in the same posture toward the heroic economy: sponsor of its balances, not its deeds.""")

add_para('gilgamesh', 'created a man of Anu', """The Old Babylonian version reframes him as the problem to be engineered against. The people of Erech, ground down by his tyranny, appeal upward, and 'Aruru upon hearing this created a man of Anu in her heart' [68]: Enkidu as counter-force, divinely tooled. By the Sumerian witness the character has already aged into its later weights, exterminator at the tree, bankrupt partner of death [17]; the Akkadian stratum keeps the fresher story: his excess calls the response into being.""")

add_para('enkidu', 'man of Anu', """In the Old Babylonian stratum he is not a companion the hero wins but a device the gods build: created by Aruru 'a man of Anu in her heart' [68], at the people's petition, to oppose a tyrant. The Sumerian poem keeps only the servant's obedience inverted [17]; between the two, the tradition records its own theory of disposition, choosing wildness as the calibrated remedy for surplus kingship, and then billing both prototypes for the lesson.""")

