# Rewrite the slop claim on franklin/washington
for e in g['edges']:
    if e['from'] == 'benjamin-franklin' and e['to'] == 'george-washington':
        if 'same pour' in e['essay'] or 'the same pour' in e['essay']:
            e['essay'] = """Two biographies the young republic bought in bulk. Weems stamps Washington 'Cincinnatus-like' at the plough [15], a Roman mold rented outright. Franklin needs no rental: his Autobiography liquidates the printing business on his own arithmetic, 'I flatter'd myself that, by the sufficient tho' moderate fortune I had acquir'd, I had secured leisure during the rest of my life for philosophical studies and amusements' [40]. The resemblance is enacted and contemporary, not transmitted: neither text cites Livy, and no carrier links Franklin to the Roman exemplum."""
            e['title'] = 'The apron and the plough, no rental'
